function getDynamicUiText() {
  return dynamicUiDict[CURRENT_LANG] || dynamicUiDict.he;
}

function getCurrentLocale() {
  return getDynamicUiText().locale;
}

function formatLocalizedDate(date, options) {
  return new Intl.DateTimeFormat(getCurrentLocale(), options).format(date);
}

function formatLocalizedTime(value) {
  const date = value instanceof Date ? value : new Date(value);
  return isNaN(date)
    ? "--:--"
    : date.toLocaleTimeString(getCurrentLocale(), {
        hour: "2-digit",
        minute: "2-digit",
      });
}

function formatDaysUntilText(days) {
  const ui = getDynamicUiText();
  return days <= 0 ? ui.today : ui.inDays(days);
}

function updateCalendarWeekdayHeaders() {
  const headers = document.querySelectorAll(".cal-grid .cal-header");
  const labels = getDynamicUiText().weekdayHeaders;
  headers.forEach((header, index) => {
    if (labels[index]) header.textContent = labels[index];
  });
}

function updateCurrentCityLabel() {
  const cityNameEl = document.getElementById("current-city-name");
  if (!cityNameEl || !cityNameEl.parentElement) return;
  const ui = getDynamicUiText();
  // במצב GPS — שם העיר שנשמר מה-reverse geocoding (לפני כן נדרס תמיד ל"מיקום נוכחי (GPS)")
  if (GEO_LOCATION === "GPS") {
    let _savedName = "";
    try { _savedName = localStorage.getItem("moadim_city_name") || ""; } catch (e) {}
    cityNameEl.textContent = _savedName || ui.gpsCity;
  }
  cityNameEl.parentElement.childNodes[0].nodeValue = `${ui.currentCityLabel} `;
}

function updateCompassStatusText() {
  // טקסטי המצפן נגזרים ממצב הריצה שלו (_cmp) — רענון בלבד כשהמודאל פתוח
  if (typeof _compassRender === "function") _compassRender();
}

function refreshLiveLanguageUI() {
  // בורר השפות הוסר — האלמנט אינו קיים עוד, נעדכן רק אם נמצא
  const _langInd = document.getElementById("lang-indicator");
  if (_langInd) _langInd.textContent = CURRENT_LANG.toUpperCase();
  document.documentElement.lang = CURRENT_LANG;
  document.documentElement.dir = CURRENT_LANG === "he" ? "rtl" : "ltr";
  applyTranslations();
  updateCompassDirectionLabels();
  updateCalendarWeekdayHeaders();
  updateCurrentCityLabel();
  updateNotifStatusUI();
  updateCompassStatusText();

  const omerModal = document.getElementById("omer-modal");
  if (omerModal && !omerModal.classList.contains("hidden")) {
    document.getElementById("omer-modal-text").textContent =
      generateOmerText(CURRENT_OMER_DAY);
  }

  const calendarModal = document.getElementById("calendar-modal");
  if (calendarModal && !calendarModal.classList.contains("hidden")) {
    buildMonthCalendar();
  }

  const sefariaContent = document.getElementById("sefaria-modal-content");
  const sefariaTitle = document.getElementById("sefaria-modal-title");
  if (sefariaContent) {
    sefariaContent.classList.toggle("text-left", CURRENT_LANG !== "he");
    sefariaContent.dir = CURRENT_LANG === "he" ? "rtl" : "ltr";
  }
  if (sefariaTitle) {
    sefariaTitle.classList.toggle("text-right", CURRENT_LANG === "he");
    sefariaTitle.classList.toggle("text-left", CURRENT_LANG !== "he");
  }
}

function bindModalBackdropClose(modalId, closeHandler) {
  const modal = document.getElementById(modalId);
  if (!modal || modal.dataset.backdropCloseBound === "true") return;
  modal.addEventListener("click", (event) => {
    if (event.target === modal) closeHandler();
  });
  modal.dataset.backdropCloseBound = "true";
}

function setupModalBackdropClose() {
  bindModalBackdropClose("settings-modal", () => {
    const modal = document.getElementById("settings-modal");
    if (modal && !modal.classList.contains("hidden")) toggleSettings();
  });
  bindModalBackdropClose("omer-modal", closeOmerModal);
  bindModalBackdropClose("sefaria-modal", closeSefariaModal);
  bindModalBackdropClose("compass-modal", function(){
    // ghost-tap: הלחיצה שפתחה את המצפן (כפתור בכותרת התפילה) נוחתת על הרקע — לא לסגור מיד
    var cm = document.getElementById("compass-modal");
    if (cm && Date.now() - (cm.__openedAt || 0) < 600) return;
    window._closePopupViaBack("compass-modal");
  });
  bindModalBackdropClose("calendar-modal", closeCalendar);
  bindModalBackdropClose("chok-israel-modal", closeChokLeIsraelModal);
}

// --- Navbar Scroll Logic ---
// מחליפים מחלקות רק כשחוצים את הסף — עבודה על כל אירוע גלילה גורמת לריצודים בנייד
let _navScrolledState = null;
window.addEventListener("scroll", () => {
  // בזמן שפופאפ נועל את הרקע scrollY קורס ל-0 — עדכון הניווט אז מהבהב מתחת לשכבה
  if (document.body.style.position === "fixed") return;
  const scrolledNow = window.scrollY > 50;
  if (scrolledNow === _navScrolledState) return;
  _navScrolledState = scrolledNow;
  const navButtons = document.querySelectorAll(".nav-action-btn");
  if (window.scrollY > 50) {
    navButtons.forEach((btn) => {
      btn.classList.remove(
        "bg-white/10",
        "text-white",
        "border-white/20",
        "hover:bg-white/20",
      );
      btn.classList.add(
        "bg-white/90",
        "text-slate-800",
        "border-slate-200",
        "hover:bg-slate-100",
        "dark:bg-slate-800",
        "dark:text-white",
        "dark:border-slate-700",
        "dark:hover:bg-slate-700",
      );
    });
  } else {
    navButtons.forEach((btn) => {
      btn.classList.add(
        "bg-white/10",
        "text-white",
        "border-white/20",
        "hover:bg-white/20",
      );
      btn.classList.remove(
        "bg-white/90",
        "text-slate-800",
        "border-slate-200",
        "hover:bg-slate-100",
        "dark:bg-slate-800",
        "dark:text-white",
        "dark:border-slate-700",
        "dark:hover:bg-slate-700",
      );
    });
  }
});

// --- Modal Scroll Lock & History Management ---
let _modalScrollLockCount = 0;
function lockBodyScroll() {
  _modalScrollLockCount++;
  if (_modalScrollLockCount === 1) {
    // (09/2026) מיקום הגלילה ביציאה מחלון — בידי האתר, לא הדפדפן. הנעילה מאפסת את scrollY
    // ודוחפים רשומת היסטוריה; ביציאה (X / חזור) unlockBodyScroll מחזיר בדיוק למקום. במצב
    // "auto" הדפדפן, *אחרי* ה-popstate, "משחזר" לרשומה את מיקום הגלילה ששמר לה — ואם שמר
    // אותו אחרי שהנעילה כבר איפסה את הגלילה (תלוי תזמון; בטלפון כמעט תמיד) זה 0: כל יציאה
    // מחלון/ספר/מצפן זרקה לראש הדף. manual = רק הקוד שלנו מזיז את הגלילה. נקבע כאן (ולא
    // בטעינה) כי זה חל על הרשומה הנוכחית: בטעינה זה היה קוטע את השחזור הרגיל של הדפדפן
    // בחזרה מדף אחר (נמדד: חזרה 860px נמוך מהמקום). בעזיבה לדף אחר — חזרה ל-auto (pagehide)
    try { if ("scrollRestoration" in history && history.scrollRestoration !== "manual") history.scrollRestoration = "manual"; } catch (e) {}
    // חובה לקרוא את מיקום הגלילה לפני position:fixed — ההצבה מאפסת את window.scrollY,
    // וקריאה אחריה שמרה תמיד 0: הרקע קפץ לראש הדף בפתיחה והסגירה החזירה לראש במקום למקום האמיתי
    const y = window.scrollY;
    // בלי body.style.touchAction (היה "pan-y"): שינוי touch-action על body מחשב מחדש את
    // כל עץ האלמנטים — 133–281ms בכל פתיחה ועוד כמעט כך בסגירה, במעבד טלפון (נמדד
    // 09/2026). אותה התנהגות קבועה ב-CSS על שכבות-העל עצמן (style.css, "touch-action לשכבות")
    document.body.style.overflow = "hidden";
    document.body.style.position = "fixed";
    document.body.style.width = "100%";
    document.body.style.top = `-${y}px`;
    document.body.dataset.scrollY = y;
  }
  _syncModalOpenClass();
}
function unlockBodyScroll() {
  // שחרור עודף (סגירה כפולה / רשומה יתומה) — אין נעילה לשחרר, לא מזיזים את הגלילה
  if (_modalScrollLockCount === 0) return;
  _modalScrollLockCount--;
  if (_modalScrollLockCount === 0) {
    const scrollY = parseInt(document.body.dataset.scrollY || "0", 10);
    document.body.style.overflow = "";
    document.body.style.position = "";
    document.body.style.width = "";
    document.body.style.top = "";
    window.scrollTo(0, scrollY);
  }
  _syncModalOpenClass();
}
// ── עזרי אבטחה גלובליים ──
// escaping למחרוזת בודדת (שם אירוע, הערת משתמש, כותרת) לפני שילוב ב-innerHTML
function escapeHtml(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
// חיטוי HTML שמקורו חיצוני שאינו בשליטתנו (דפי מקור של ספריא, ויקיטקסט וכד')
// תאריך "YYYY-MM-DD" → חצות מקומית. new Date("YYYY-MM-DD") מפרש כ-UTC, ובאזורי זמן
// מערבית ל-UTC (למשל ארה"ב) מחזיר את היום הקודם ⇒ ימי שבוע וספירת ימים שגויים.
function parseLocalDate(v) {
  if (typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v)) {
    const p = v.split("-");
    return new Date(+p[0], +p[1] - 1, +p[2]);
  }
  return new Date(v);
}
