      context.isRoshChodesh || context.isChanukah || context.isPurim ||
      context.isShushanPurim || /Purim Katan|פורים קטן/.test(_evS) ||
      !!context.isNoTachanun;
    // מוצאי שבת / יו"ט / ר"ח — עד חצות הלילה
