    var _prevIso = _prevHeb.getFullYear() + "-" + String(_prevHeb.getMonth() + 1).padStart(2, "0") +
      "-" + String(_prevHeb.getDate()).padStart(2, "0");
    var _motzaeiRC = (window.ALL_EVENTS_FULL || window.ALL_EVENTS || []).some(function (e) {
      return e && e.date === _prevIso && /Rosh Chodesh|ראש חודש/.test((e.titleStr || "") + " " + (e.heb || "") + " " + (e.name || ""));
    });
