  var dt = context.displayDate && typeof context.displayDate.getDay === "function" && !isNaN(context.displayDate.getTime()) ? context.displayDate : null;
  var dow = dt ? dt.getDay() : context.isShabbat ? 6 : -1;
  // בשבת אין נוטלים לולב (גזירה שמא יעבירנו ד' אמות)
  if (dow === 6) return "";
