  var hr = '<hr class="prayer-divider">';
  var d = context.displayDate || new Date();
  var dow = d.getDay();
  var mon = d.getMonth();
  // "קיץ" לעניין משיב הרוח/מוריד הטל — לפי התאריך העברי המדויק כשקיים
  // (מוריד הטל: מט"ו ניסן עד שמיני עצרת), עם נסיגה להיוריסטיקה הלועזית הישנה
  var isSummer = context.hasHebDate ? !context.isWinterPraise : (context.isPesach || (mon >= 3 && mon <= 8 && !context.isSukkot));
  // "ותן טל ומטר" (ברכת השנים) — רק מליל ז' חשוון; בין שמיני עצרת לז' חשוון
  // אומרים משיב הרוח אבל עדיין בלי שאלת גשמים
  var isRainRequest = context.hasHebDate ? context.isRainRequest : !isSummer;
  // מוצ"ש / מוצאי יו"ט — מקור אמת משותף (_maarivMotzaeiState): בלילה רגיל שום תוספת
  var mz = _maarivMotzaeiState(context, "sfard");
  var isMotzaeiShabbat = mz.motzash;
  var parts = [];

  // ─── פתיחה + ברכו ───
  parts.push(sup(p("<small><small>כשיגיע הלילה יתפלל תפלת ערבית. ואינה חובה שלא נתקנה אלא כנגד איברים ופדרים של תמיד של בין הערבים שלא נתעכלו ביום שקרבין והולכין כל הלילה. ומ\"מ מצוה איכא ואין לבטלה. ורב אלפס כתב דהאידנא קבעוה חובה ואין לבטלה כלל (טור או\"ח רל\"ה)</small></small>")));
  if (!context.isShabbat || isMotzaeiShabbat) {
    parts.push(p("וְהוּא רַחוּם יְכַפֵּר עָוֹן וְלֹא־יַשְׁחִית וְהִרְבָּה לְהָשִׁיב אַפּוֹ וְלֹא־יָעִיר כָּל־חֲמָתוֹ: יְהֹוָה הוֹשִׁיעָה הַמֶּֽלֶךְ יַעֲנֵֽנוּ בְיוֹם־קָרְאֵֽנוּ:"));
  }
  parts.push(p("<small>ואומר שליח צבור:</small>"));
  parts.push(p("<b>בָּרְ֒כוּ אֶת יְהֹוָה הַמְּ֒בֹרָךְ:</b>"));
  parts.push(p("<small>ועונין הקהל:</small>"));
  parts.push(p("<b>בָּרוּךְ</b> יְהֹוָה הַמְּ֒בֹרָךְ לְעוֹלָם וָעֶד:"));
  parts.push(hr);

  // ─── ברכות קריאת שמע ───
  parts.push(p("<b>בָּרוּךְ</b> אַתָּה יְהֹוָה אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם אֲשֶׁר בִּדְבָרוֹ מַעֲרִיב עֲרָבִים בְּחָכְמָה פּוֹתֵֽחַ שְׁעָרִים וּבִתְבוּנָה מְשַׁנֶּה עִתִּים וּמַחֲלִיף אֶת הַזְּ֒מַנִּים וּמְסַדֵּר אֶת הַכּוֹכָבִים בְּמִשְׁמְ֒רוֹתֵיהֶם בָּרָקִֽיעַ כִּרְצוֹנוֹ. בּוֹרֵא יוֹם וָלָֽיְלָה גּוֹלֵל אוֹר מִפְּ֒נֵי חֽשֶׁךְ וְחֽשֶׁךְ מִפְּ֒נֵי אוֹר וּמַעֲבִיר יוֹם וּמֵבִיא לָֽיְלָה וּמַבְדִּיל בֵּין יוֹם וּבֵין לָֽיְלָה יְהֹוָה צְבָאוֹת שְׁמוֹ: אֵל חַי וְקַיָּם תָּמִיד יִמְלֹךְ עָלֵֽינוּ לְעוֹלָם וָעֶד. בָּרוּךְ אַתָּה יְהֹוָה הַמַּעֲרִיב עֲרָבִים:"));
  parts.push(p("אַהֲבַת עוֹלָם בֵּית יִשְׂרָאֵל עַמְּ֒ךָ אָהָֽבְתָּ תּוֹרָה וּמִצְוֹת חֻקִּים וּמִשְׁפָּטִים אוֹתָֽנוּ לִמַּֽדְתָּ. עַל כֵּן יְהֹוָה אֱלֹהֵֽינוּ בְּשָׁכְבֵֽנוּ וּבְקוּמֵֽנוּ נָשִֽׂיחַ בְּחֻקֶּֽיךָ וְנִשְׂמַח בְּדִבְרֵי תַלמוּד תּוֹרָתֶֽךָ וּבְמִצְוֹתֶֽיךָ לְעוֹלָם וָעֶד. כִּי הֵם חַיֵּֽינוּ וְאֹֽרֶךְ יָמֵֽינוּ וּבָהֶם נֶהְגֶּה יוֹמָם וָלָֽיְלָה. וְאַהֲבָתְ֒ךָ אַל תָּסִיר מִמֶּֽנּוּ לְעוֹלָמִים. בָּרוּךְ אַתָּה יְהֹוָה אוֹהֵב עַמּוֹ יִשְׂרָאֵל:"));
  parts.push(sup(p("<small><small>יחיד אומר</small></small>")));
  parts.push(p("אֵל מֶֽלֶךְ נֶאֱמָן:"));
  parts.push(p("<b>שְׁמַע יִשְׂרָאֵל יְהֹוָה אֱלֹהֵֽינוּ יְהֹוָה אֶחָד:</b>"));
  parts.push(sup(p("<small><small>יש להפסיק מעט בין אחד לברוך כי עיקר קבול עול מלכות שמים היא פסוק ראשון. ויאמר בלחש:</small></small>")));
  parts.push(p("בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד:"));
  parts.push(p("<b>וְאָהַבְתָּ</b> אֵת יְהֹוָה אֱלֹהֶֽיךָ בְּכָל֯־לְ֯בָבְ֒ךָ וּבְכָל־נַפְשְׁךָ וּבְכָל־מְאֹדֶֽךָ: וְהָיוּ הַדְּ֒בָרִים הָאֵֽלֶּה אֲשֶׁר֯ אָ֯נֹכִי מְצַוְּ֒ךָ הַיּוֹם עַל֯־לְ֯בָבֶֽךָ: וְשִׁנַּנְתָּם לְבָנֶֽיךָ וְדִבַּרְתָּ בָּם בְּשִׁבְתְּ֒ךָ בְּבֵיתֶֽךָ וּבְ֒לֶכְתְּךָ בַדֶּֽרֶךְ וּבְ֒שָׁכְבְּךָ וּבְ֒קוּמֶֽךָ: וּקְ֒שַׁרְתָּם לְאוֹת עַל֯־יָ֯דֶֽךָ וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶֽיךָ: וּכְ֒תַבְתָּם עַל־מְזֻזוֹת בֵּיתֶֽךָ וּבִשְׁ֒עָרֶֽיךָ:"));
  parts.push(p("וְהָיָה אִם־שָׁמֹֽעַ תִּשְׁמְעוּ אֶל־מִצְוֹתַי אֲשֶׁר֯ אָ֯נֹכִי מְצַוֶּה אֶתְ֒כֶם הַיּוֹם לְאַהֲבָה אֶת־יְהֹוָה אֱלֹהֵיכֶם וּלְ֒עָבְ֒דוֹ בְּכָל־לְבַבְ֒כֶם וּבְכָל־נַפְשְׁכֶם: וְנָתַתִּי מְטַר֯־אַ֯רְצְכֶם בְּעִתּוֹ יוֹרֶה וּמַלְקוֹשׁ וְאָסַפְתָּ דְגָנֶֽךָ וְתִירשְׁךָ וְיִצְהָרֶֽךָ: וְנָתַתִּי עֵֽשֶׂב֯ בְּ֯שָׂדְ֒ךָ לִבְ֒הֶמְתֶּֽךָ וְאָכַלְתָּ וְשָׂבָֽעְתָּ: הִשָּׁמְ֒רוּ לָכֶם פֶּן֯־יִ֯פְתֶּה לְבַבְ֒כֶם וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים֯ אֲ֯חֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם: וְחָרָה אַף־יְהֹוָה בָּכֶם וְעָצַר֯ אֶ֯ת־הַשָּׁמַֽיִם וְלֹּא֯־יִ֯הְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת֯־יְ֯בוּלָהּ וַאֲבַדְתֶּם֯ מְ֯הֵרָה מֵעַל הָאָֽרֶץ הַטֹּבָה אֲשֶׁר֯ יְ֯הֹוָה נֹתֵן לָכֶם: וְשַׂמְתֶּם֯ אֶ֯ת־דְּבָרַי֯ אֵֽ֯לֶּה עַל֯־לְ֯בַבְ֒כֶם וְעַל־נַפְשְׁ֒כֶם וּקְ֒שַׁרְתֶּם֯ אֹ֯תָם לְאוֹת עַלּ־יֶּדְ֒כֶם וְהָיוּ לְטוֹטָפֹת בֵּין עֵינֵיכֶם: וְלִמַּדְתֶּם֯ אֹ֯תָם אֶת־בְּנֵיכֶם לְדַבֵּר בָּם בְּשִׁבְתְּךָ בְּבֵיתֶֽךָ וּבְ֒לֶכְתְּ֒ךָ בַדֶּֽרֶךְ וּבְ֒שָׁכְבְּ֒ךָ וּבְ֒קוּמֶֽךָ: וּכְ֒תַבְתָּם עַל־מְזוּזוֹת בֵּיתֶֽךָ וּבִשְׁ֒עָרֶֽיךָ: לְמַֽעַן֯ יִ֯רְבּוּ יְמֵיכֶם וִימֵי בְנֵיכֶם עַל הָאֲדָמָה אֲשֶׁר נִשְׁבַּע יְהֹוָה לַאֲבֹתֵיכֶם לָתֵת לָהֶם כִּימֵי הַשָּׁמַֽיִם עַל־הָאָֽרֶץ:"));
  parts.push(p("וַֽיֹּאמֶר֯ יְהֹוָה אֶ֯ל־משֶׁה לֵּאמֹר: דַּבֵּר֯ אֶ֯ל־בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם וְעָשׂוּ לָהֶם צִיצִת עַל־כַּנְ֒פֵי בִגְ֒דֵיהֶם לְדֹרֹתָם וְנָתְ֒נוּ עַל־צִיצִת הַכָּנָף֯ פְּ֯תִיל תְּכֵֽלֶת: וְהָיָה לָכֶם לְצִיצִת וּרְ֒אִיתֶם֯ אֹ֯תוֹ וּזְ֒כַרְתֶּם֯ אֶ֯ת־כָּל־מִצְוֹת֯ יְ֯הֹוָה וַעֲשִׂיתֶם֯ אֹ֯תָם וְלֹא תָתֽוּרוּ אַחֲרֵי לְבַבְ֒כֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר֯־אַ֯תֶּם זֹנִים֯ אַ֯חֲרֵיהֶם: לְמַֽעַן תִּזְכְּרוּ וַעֲשִׂיתֶם֯ אֶ֯ת־כָּל־מִצְוֹתָי וִהְיִיתֶם קְדשִׁים לֵאלֹהֵיכֶם: אֲנִי יְהֹוָה אֱלֹהֵיכֶם֯ אֲ֯שֶׁר הוֹצֵֽאתִי אֶתְ֒כֶם֯ מֵּאֶֽרֶץ מִצְרַֽיִם לִהְיוֹת לָכֶם לֵאלֹהִים֯ אֲ֯נִי יְהֹוָה אֱלֹהֵיכֶם֯:"));
  parts.push(p("<small>יש לצרף <b>אֱלֹהֵיכֶם</b> ל<b>אֱמֶת</b></small>"));
  parts.push(p("אֱ֯מֶת"));
  parts.push(p("<small>שליח ציבור:</small>"));
  parts.push(p("<b>יְהֹוָה אֱלֹהֵיכֶם֯ אֱ֯מֶת:</b>"));
  parts.push(sup(p("<small><small>אמת ואמונה אינה פותחת בברוך דהויא סמוכה לחבירתה דק\"ש לא הוי הפסק (טור או\"ח רלו)</small></small>")));
  parts.push(p("<b>וֶאֱמוּנָה</b> כָּל זֹאת וְקַיָּם עָלֵֽינוּ כִּי הוּא יְהֹוָה אֱלֹהֵֽינוּ וְאֵין זוּלָתוֹ וַאֲנַֽחְנוּ יִשְׂרָאֵל עַמּוֹ: הַפּוֹדֵֽנוּ מִיַּד מְלָכִים מַלְכֵּֽנוּ הַגּוֹאֲלֵֽנוּ מִכַּף כָּל הֶעָרִיצִים: הָאֵל הַנִּפְרָע לָֽנוּ מִצָּרֵֽינוּ וְהַמְ֒שַׁלֵּם גְּמוּל לְכָל אֹיְ֒בֵי נַפְשֵֽׁנוּ: הָעֹשֶׂה גְדוֹלוֹת עַד אֵין חֵֽקֶר נִסִּים וְנִפְלָאוֹת עַד אֵין מִסְפָּר: הַשָּׂם נַפְשֵֽׁנוּ בַּחַיִּים וְלֹא נָתַן לַמּוֹט רַגְלֵֽנוּ הַמַּדְרִיכֵֽנוּ עַל בָּמוֹת אֹיְ֒בֵֽינוּ וַיָּֽרֶם קַרְנֵֽנוּ עַל כָּל שׂוֹנְ֒אֵֽינוּ: הָעֹֽשֶׂה לָּֽנוּ נִסִּים וּנְקָמָה בְּפַרְעֹה אוֹתוֹת וּמוֹפְ֒תִים בְּאַדְמַת בְּנֵי חָם: הַמַּכֶּה בְעֶבְרָתוֹ כָּל בְּכוֹרֵי מִצְרָֽיִם וַיּוֹצֵא אֶת עַמּוֹ יִשְׂרָאֵל מִתּוֹכָם לְחֵרוּת עוֹלָם: הַמַּעֲבִיר בָּנָיו בֵּין גִּזְרֵי יַם סוּף אֶת רוֹדְ֒פֵיהֶם וְאֶת שׂוֹנְ֒אֵיהֶם בִּתְהוֹמוֹת טִבַּע: וְרָאוּ בָנָיו גְּבוּרָתוֹ שִׁבְּ֒חוּ וְהוֹדוּ לִשְׁמוֹ. וּמַלְכוּתוֹ בְרָצוֹן קִבְּ֒לוּ עֲלֵיהֶם משֶׁה וּבְנֵי יִשְׂרָאֵל לְךָ עָנוּ שִׁירָה בְּשִׂמְחָה רַבָּה וְאָמְ֒רוּ כֻלָּם:"));
  parts.push(p("<b>מִי כָמֹֽכָה</b> בָּאֵלִם יְהֹוָה מִי כָּמֹֽכָה נֶאְדָּר בַּקֹּֽדֶשׁ נוֹרָא תְהִלֹּת עֹֽשֵׂה פֶלֶא: מַלְכוּתְךָ רָאוּ בָנֶֽיךָ בּוֹקֵֽעַ יָם לִפְנֵי משֶׁה זֶה אֵלִי עָנוּ וְאָמְ֒רוּ:"));
  parts.push(p("יְהֹוָה יִמְלֹךְ לְעֹלָם וָעֶד: וְנֶאֱמַר כִּי פָדָה יְהֹוָה אֶת יַעֲקֹב וּגְאָלוֹ מִיַּד חָזָק מִמֶּֽנּוּ. בָּרוּךְ אַתָּה יְהֹוָה גָּאַל יִשְׂרָאֵל:"));
  parts.push(sup(p("<small><small>אומר השכיבנו וחותם שומר את עמו ישראל לעד מפני שלילה צריכה שימור מן המזיקין. ואע\"ג דקי\"ל כרבי יוחנן דאמר שצריך לסמוך אף גאולה של ערבית לתפלת ערבית השכיבנו לא הוי הפסק דכיון דתקינו ליה רבנן כגאולה אריכתא (טור או\"ח רלו)</small></small>")));
  parts.push(p("<b>הַשְׁכִּיבֵֽנוּ</b> יְהֹוָה אֱלֹהֵֽינוּ לְשָׁלוֹם וְהַעֲמִידֵֽנוּ מַלְכֵּֽנוּ לְחַיִּים טוֹבִים וּלְשָׁלוֹם וּפְרוֹשׂ עָלֵֽינוּ סֻכַּת שְׁלוֹמֶֽךָ וְתַקְּ֒נֵֽנוּ בְּעֵצָה טוֹבָה מִלְּ֒פָנֶֽיךָ וְהוֹשִׁיעֵֽנוּ מְהֵרָה לְמַֽעַן שְׁמֶֽךָ. וְהָגֵן בַּעֲדֵֽנוּ וְהָסֵר מֵעָלֵֽינוּ אוֹיֵב דֶּֽבֶר וְחֶֽרֶב וְרָעָב וְיָגוֹן וְהָסֵר שָׂטָן מִלְּ֒פָנֵֽינוּ וּמֵאַחֲרֵֽינוּ וּבְצֵל כְּנָפֶֽיךָ תַּסְתִּירֵֽנוּ. כִּי אֵל שׁוֹמְ֒רֵֽנוּ וּמַצִּילֵֽנוּ אָֽתָּה כִּי אֵל מֶֽלֶךְ חַנּוּן וְרַחוּם אָֽתָּה. וּשְׁמוֹר צֵאתֵֽנוּ וּבוֹאֵֽנוּ לְחַיִּים וּלְשָׁלוֹם מֵעַתָּה וְעַד עוֹלָם. בָּרוּךְ אַתָּה יְהֹוָה שׁוֹמֵר עַמּוֹ יִשְׂרָאֵל לָעַד:"));
  parts.push(sup(p("<small><small>מה שנוהגין להפסיק בפסוקים ויראו עינינו וקדיש לפי שבימים ראשונים היו בתי כנסיות שלהם בשדות והיו יראים להתאחר שם עד זמן תפלת ערבית ותיקנו לומר פסוקים אלו שיש בהם י\"ח אזכרות כנגד י\"ח ברכות שיש בתפלת ערבית ונפטרין בקדיש ועתה שחזרו להתפלל ערבית בבתי כנסיות לא נתבטל מנהג הראשון ומ\"מ אין להפסיק בדברים אחרים ויש מן הגדולים שנהגו שלא לאמרם (טור או\"ח רלו)</small></small>")));
  parts.push(sup(p("בָּרוּךְ יְהֹוָה לְעוֹלָם אָמֵן וְאָמֵן: בָּרוּךְ יְהֹוָה מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלָֽםִ הַלְ֒לוּיָהּ: בָּרוּךְ יְהֹוָה אֱלֹהִים אֱלֹהֵי יִשְׂרָאֵל עֹשֵׂה נִפְלָאוֹת לְבַדּוֹ: וּבָרוּךְ שֵׁם כְּבוֹדוֹ לְעוֹלָם וְיִמָּלֵא כְבוֹדוֹ אֶת כָּל הָאָֽרֶץ אָמֵן וְאָמֵן: יְהִי כְבוֹד יְהֹוָה לְעוֹלָם יִשְׂמַח יְהֹוָה בְּמַעֲשָׂיו: יְהִי שֵׁם יְהֹוָה מְבֹרָךְ מֵעַתָּה וְעַד עוֹלָם: כִּי לֹא יִטּשׁ יְהֹוָה אֶת עַמּוֹ בַּעֲבוּר שְׁמוֹ הַגָּדוֹל כִּי הוֹאִיל יְהֹוָה לַעֲשׂוֹת אֶתְכֶם לוֹ לְעָם: וַיַּרְא כָּל הָעָם וַיִּפְּ֒לוּ עַל פְּנֵיהֶם וַיֹּאמְ֒רוּ יְהֹוָה הוּא הָאֱלֹהִים יְהֹוָה הוּא הָאֱלֹהִים: וְהָיָה יְהֹוָה לְמֶֽלֶךְ עַל כָּל הָאָֽרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְהֹוָה אֶחָד וּשְׁמוֹ אֶחָד: יְהִי חַסְדְּ֒ךָ יְהֹוָה עָלֵֽינוּ כַּאֲשֶׁר יִחַֽלְנוּ לָךְ: הוֹשִׁיעֵֽנוּ יְהֹוָה אֱלֹהֵֽינוּ וְקַבְּ֒צֵֽנוּ מִן הַגּוֹיִם לְהוֹדוֹת לְשֵׁם קָדְשֶֽׁךָ לְהִשְׁתַּבֵּֽחַ בִּתְהִלָּתֶֽךָ: כָּל גּוֹיִם אֲשֶׁר עָשִֽׂיתָ יָבֹֽאוּ וְיִשְׁתַּחֲווּ לְפָנֶֽיךָ אֲדֹנָי וִיכַבְּ֒דוּ לִשְׁמֶֽךָ: כִּי גָדוֹל אַתָּה וְעֹשֵׂה נִפְלָאוֹת אַתָּה אֱלֹהִים לְבַדֶּֽךָ: וַאֲנַֽחְנוּ עַמְּ֒ךָ וְצֹאן מַרְעִיתֶֽךָ נוֹדֶה לְּךָ לְעוֹלָם לְדוֹר וָדוֹר נְסַפֵּר תְּהִלָּתֶֽךָ: בָּרוּךְ יְהֹוָה בַּיּוֹם בָּרוּךְ יְהֹוָה בַּלָּֽיְלָה בָּרוּךְ יְהֹוָה בְּשָׁכְבֵֽנוּ בָּרוּךְ יְהֹוָה בְּקוּמֵֽנוּ: כִּי בְיָדְ֒ךָ נַפְשׁוֹת הַחַיִּים וְהַמֵּתִים אֲשֶׁר בְּיָדוֹ נֶֽפֶשׁ כָּל חָי וְרֽוּחַ כָּל בְּשַׂר אִישׁ: בְּיָדְ֒ךָ אַפְקִיד רוּחִי פָּדִֽיתָה אוֹתִי יְהֹוָה אֵל אֱמֶת: אֱלֹהֵֽינוּ שֶׁבַּשָּׁמַֽיִם יַחֵד שִׁמְךָ וְקַיֵּם מַלְכוּתְ֒ךָ תָּמִיד וּמְלֹךְ עָלֵֽינוּ לְעוֹלָם וָעֶד:")));
