window.copyContactEmail = function (btn) {
  const email = "zstore.ai295@gmail.com";
  const showToast = () => {
    let toast = document.getElementById("contact-copy-toast");
    if (toast) toast.remove();
    toast = document.createElement("div");
    toast.id = "contact-copy-toast";
    toast.textContent = "✓ הכתובת הועתקה ללוח";
    toast.style.cssText =
      "position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:9999;background:#16a34a;color:white;font-weight:700;padding:0.85rem 1.5rem;border-radius:1rem;box-shadow:0 10px 30px rgba(0,0,0,0.25);font-size:0.95rem;direction:rtl;animation:fadeInOut 1.6s ease forwards;";
    document.body.appendChild(toast);
    setTimeout(() => {
      if (toast && toast.parentNode) toast.remove();
    }, 1600);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(email).then(showToast, () => {
      // Fallback
      const ta = document.createElement("textarea");
      ta.value = email;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
      } catch (e) {}
      document.body.removeChild(ta);
      showToast();
    });
  } else {
    const ta = document.createElement("textarea");
    ta.value = email;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    try {
      document.execCommand("copy");
    } catch (e) {}
    document.body.removeChild(ta);
    showToast();
  }
};

openPrayer = async function (key, heLabel, enLabel) {
  const doOpen = async () => {
    const entry = PRAYER_DB[key] || { title: heLabel || enLabel || key };
    const isPopup = false;
    // מעבר ישיר מתפילה לתפילה (כפתור "המשך ל..." בסוף התפילה): המודאל מוחלף במקום —
    // רשומת ההיסטוריה של הקודם מוחלפת (replaceState), כך ש"חזרה" אחת סוגרת ולא נשאר עודף
    const swapInPlace = !!window.__prayerSwapInPlace && !!document.getElementById("prayer-modal");
    window.__prayerSwapInPlace = false;
    renderPrayerModalShell(entry.title || heLabel || enLabel || key, isPopup, key);
    lockBodyScroll();
    if (swapInPlace) {
      _activeModals.push("prayer-modal");
      try { history.replaceState({ modal: "prayer-modal" }, ""); } catch (e) {}
    } else {
      pushModalState("prayer-modal");
    }
    const _ph = _uxPhMark();
    try {
      const content = await getFullPrayerContent(key);
      const meta = document.getElementById("prayer-modal-meta");
      const body = document.getElementById("prayer-modal-body");
      if (meta) {
        // נוסח בלבד; קרדיט המקור הועבר לסיום הטקסט
        meta.innerHTML = `נוסח: <strong>${content.nusachLabel}</strong>`;
      }
      if (body) {
        if (isPopup) {
          body.innerHTML = `
                <div style="display:flex;flex-direction:column;min-height:0;max-height:100%;height:100%;">
                  <div class="holy-text-style" style="flex:1;min-height:0;overflow-y:auto;padding-inline-end:0.35rem;padding-bottom:0.35rem;direction:rtl;text-align:center;">
                    ${content.seasonalHtml}
                    ${content.html}
                  </div>
                  <div style="border-top:1px solid rgba(0,0,0,0.08);margin-top:0.85rem;padding-top:0.75rem;color:#94a3b8;font-size:0.72rem;text-align:center;">
                    מקור התוכן: <strong>${content.sourceLabel}</strong>${content.sourceUrl ? ` · <a href="${content.sourceUrl}" target="_blank" rel="noopener noreferrer" style="color:#1d4ed8;">קישור למקור</a>` : ""}
                  </div>
                </div>`;
        } else {
          body.innerHTML = `
                <div class="holy-text-style" style="direction:rtl;text-align:center;">
                  ${content.seasonalHtml ? '<div style="background:rgba(59,130,246,0.06);border:1px solid rgba(59,130,246,0.18);border-radius:0.75rem;padding:0.7rem 0.85rem;margin-bottom:1.25rem;font-size:0.82em;color:#1e40af;line-height:1.65;border-right:3px solid rgba(37,99,235,0.4);">' + content.seasonalHtml + "</div>" : ""}
                  ${content.html}
                </div>
                ${_prayerNextCtaHtml(key)}
                <div style="border-top:1px solid rgba(0,0,0,0.08);margin-top:1.5rem;padding-top:0.75rem;color:#94a3b8;font-size:0.72rem;text-align:center;">
                  מקור התוכן: <strong>${content.sourceLabel}</strong>${content.sourceUrl ? ` · <a href="${content.sourceUrl}" target="_blank" rel="noopener noreferrer" style="color:#3b82f6;">קישור למקור</a>` : ""}
                </div>`;
        }
      }
      // מנחה / ברכת המזון נפתחות ישר בעוגן — כבר לפני הציור הראשון. עד 09/2026 רק אחרי 120ms:
      // הטקסט הופיע מראשו ואז "קפץ" לעוגן. (הקריאות ב-120/500ms למטה נשארות כבדיקה חוזרת)
      const _anchor = key === "mincha" ? "mincha-korbanot-start" : key === "birkat-hamazon" ? "birkat-hamazon-start" : null;
      if (_anchor) scrollPrayerToAnchor(_anchor);
      // הטקסט שהגיע אחרי "טוען..." נכנס ברכות (ראו _uxSoftIn) — אחרי הגלילה לעוגן, כדי שהמדידה
      // שלה תיעשה על המיקום הסופי ולא על תוכן באמצע תנועה
      if (body && typeof window._uxSoftIn === "function") window._uxSoftIn(body.children, _ph);
      // ברכת הלבנה: זמני החודש והמצב העדכני (תחילה/סוף לפי המולד) בבאנר העליון
      if (key === "kiddush-levana" && body) {
        try { _levanaFillPrayerTimes(body); } catch (e) {}
      }
      // תיקון חצות: מה אומרים הלילה (רחל ולאה / לאה בלבד / רחל בלבד / אין אומרים) — מחושב בכל פתיחה
      if (key === "tikkun-chatzot" && body) {
        try { _tikkunChatzotApply(body); } catch (e) {}
      }
      // מנחה נפתחת ישירות בקורבנות (למנצח על הגיתית); אפשר לגלול מעלה לפתח אליהו
      if (key === "mincha") {
        setTimeout(function () { scrollPrayerToAnchor("mincha-korbanot-start"); }, 120);
        setTimeout(function () { scrollPrayerToAnchor("mincha-korbanot-start"); }, 500);
      }
      // ברכת המזון נפתחת ישירות בברכה הראשונה ("ברוך אתה... הזן");
      // המזמורים והזימון נגישים בגלילה מעלה (בקשת משתמש 09/2026)
      if (key === "birkat-hamazon") {
        setTimeout(function () { scrollPrayerToAnchor("birkat-hamazon-start"); }, 120);
        setTimeout(function () { scrollPrayerToAnchor("birkat-hamazon-start"); }, 500);
      }
    } catch (error) {
      const body = document.getElementById("prayer-modal-body");
      const meta = document.getElementById("prayer-modal-meta");
      if (meta) {
        meta.textContent = "לא הצלחתי לטעון נוסח מלא כעת.";
      }
      if (body) {
        body.innerHTML = `<div class="prayer-richtext"><p>אירעה שגיאה בטעינת התפילה. אפשר לנסות שוב בעוד רגע.</p></div>`;
      }
    }
  };
  ensureNusachChosen(doOpen);
};

// ── תיקון חצות לפי הלילה (09/2026) ──
// המקורות: כף החיים סימן א, בן איש חי (וישלח שנה א), ילקוט יוסף (הל' השכמת הבוקר) — ואותם הכללים
// שבהוראת הסידור עצמו (ספריא, סידור עדות המזרח). הלילה שייך ליום העברי שמתחיל בצאת הכוכבים:
// לפני עלות השחר — הלילה של היום העברי הנוכחי; מעלות השחר והלאה — הלילה הקרוב (של מחר).
//   אין אומרים כלל: ליל שבת, ימים טובים (ר"ה, יוה"כ, סוכות, שמיני עצרת, פסח, שבועות), חוה"מ פסח.
//   תיקון רחל בלבד: ליל תשעה באב.
//   תיקון לאה בלבד (בלי וידוי ובלי תיקון רחל): ימים שאין אומרים בהם תחנון, ימי העומר, עשרת ימי
//   תשובה, חוה"מ סוכות, אחרי המולד וקודם ראש חודש, ושנת השמיטה בארץ ישראל.
//   בימים שאין אומרים תחנון אין אומרים בתיקון לאה את "למנצח... יענך" ואת "עד אנה בכיה בציון".
function _tikkunChatzotStatus(now) {
  now = now || new Date();
  const K = window.KosherZmanim;
  if (!K || !K.JewishCalendar) return null;
  let alot = null;
  try {
    const z = window._lastZData;
    if (z && z.times && z.times.alotHaShachar) alot = new Date(z.times.alotHaShachar);
  } catch (e) {}
  // שעת עלות השחר של היום (מנתוני הזמנים), מוחלת על התאריך של now — כדי שהחישוב נכון לכל תאריך
  alot = (!alot || isNaN(alot))
    ? new Date(now.getFullYear(), now.getMonth(), now.getDate(), 4, 45)
    : new Date(now.getFullYear(), now.getMonth(), now.getDate(), alot.getHours(), alot.getMinutes());
  const base = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
  const target = now < alot ? base : new Date(base.getFullYear(), base.getMonth(), base.getDate() + 1, 12);
  const jc = new K.JewishCalendar(target);
  try { jc.setInIsrael(true); } catch (e) {}
  const m = jc.getJewishMonth(), d = jc.getJewishDayOfMonth(), yr = jc.getJewishYear();
  const leap = jc.isJewishLeapYear();
  const dow = jc.getDayOfWeek(); // 1=ראשון … 7=שבת
  const NISSAN = 1, IYAR = 2, SIVAN = 3, TAMMUZ = 4, AV = 5, ELUL = 6, TISHREI = 7, SHEVAT = 11, ADAR = 12, ADAR_II = 13;
  const nusach = typeof CURRENT_NUSACH === "string" ? CURRENT_NUSACH : "mizrahi";
  const st = { target: target, rachel: true, leah: true, noTachanun: false, reason: "", notes: [] };
  let dateLabel = "";
  try { dateLabel = getHebrewDateString(target) || ""; } catch (e) {}
  st.nightLabel = dateLabel ? "ליל " + dateLabel : "הלילה";
  // ── אין אומרים כלל ──
  let none = "";
  if (dow === 7) none = "ליל שבת";
  else if (jc.isRoshHashana()) none = "ראש השנה";
  else if (jc.isYomKippur()) none = "יום הכיפורים";
  else if (jc.isCholHamoedPesach()) none = "חול המועד פסח";
  else if (jc.isYomTovAssurBemelacha()) {
    none = m === NISSAN ? "פסח" : m === SIVAN ? "חג השבועות" : (m === TISHREI && d === 22) ? "שמיני עצרת ושמחת תורה" : "חג הסוכות";
  }
  if (none) { st.rachel = false; st.leah = false; st.reason = none; return st; }
  // ── ליל תשעה באב — תיקון רחל בלבד ──
  if (jc.isTishaBav()) { st.leah = false; st.reason = "תשעה באב"; return st; }
  // ── ימים שאין אומרים בהם תחנון (לפי מנהג הנוסח; אותה רשימה כמו בתפילות) ──
  let nt = "";
  const purimMonth = leap ? ADAR_II : ADAR;
  if (jc.isRoshChodesh()) nt = "ראש חודש";
  else if (m === NISSAN) nt = "חודש ניסן";
  else if (jc.isCholHamoedSuccos()) nt = "חול המועד סוכות";
  else if (m === TISHREI && d >= 11 && (nusach !== "ashkenaz" || d <= 23)) nt = "ימי החג שבחודש תשרי";
  else if (m === ELUL && d === 29) nt = "ערב ראש השנה";
  else if (jc.isChanukah()) nt = "חנוכה";
  else if (m === purimMonth && (d === 14 || d === 15)) nt = d === 14 ? "פורים" : "שושן פורים";
  else if (leap && m === ADAR && (d === 14 || d === 15)) nt = "פורים קטן";
  else if (m === IYAR && (d === 14 || d === 18)) nt = d === 14 ? "פסח שני" : 'ל"ג בעומר';
  else if (m === SIVAN && d <= 12) nt = "ימי חג השבועות";
  else if (m === AV && d === 15) nt = 'ט"ו באב';
  else if (m === SHEVAT && d === 15) nt = 'ט"ו בשבט';
  if (nt) { st.noTachanun = true; st.rachel = false; st.reason = nt; }
  // ── תיקון לאה בלבד אף שאומרים תחנון ──
  if (st.rachel) {
    let why = "";
    if (jc.getDayOfOmer() > 0) why = "ימי ספירת העומר";
    else if (jc.isAseresYemeiTeshuva()) why = "עשרת ימי תשובה";
    else if (yr % 7 === 0) why = "שנת השמיטה בארץ ישראל";
    else {
      // אחרי המולד וקודם ראש חודש
      try {
        if (d >= 20) {
          let nm = m + 1, ny = yr;
          if (m === ELUL) { nm = TISHREI; ny = yr + 1; }
          else if ((m === ADAR && !leap) || m === ADAR_II) nm = NISSAN;
          const nx = new K.JewishCalendar(ny, nm, 1);
          const molad = nx.getMoladAsDate();
          const ms = molad && (molad.getTime ? molad.getTime() : (molad.toJSDate ? molad.toJSDate().getTime() : (molad.toMillis ? molad.toMillis() : NaN)));
          const nightStart = new Date(target.getFullYear(), target.getMonth(), target.getDate(), 0, 30);
          if (!isNaN(ms) && ms <= nightStart.getTime()) why = "אחרי המולד וקודם ראש חודש";
        }
      } catch (e) {}
    }
    if (why) { st.rachel = false; st.reason = why; }
  }
  // בין המצרים (י"ז בתמוז – ט' באב): תיקון רחל גם בחצות היום
  if ((m === TAMMUZ && d >= 17) || (m === AV && d <= 9)) {
    st.notes.push("בימי בין המצרים נוהגים לומר תיקון רחל גם אחרי חצות היום.");
  }
  return st;
}

function _tikkunChatzotApply(body) {
  if (!body) return;
  const st = _tikkunChatzotStatus();
  const root = body.querySelector(".holy-text-style");
  const rich = root && root.querySelector(".prayer-richtext");
  if (!st || !rich) return;
  const strip = (t) => String(t || "").replace(/[֑-ׇ]/g, "").replace(/\s+/g, " ").trim();
  const ps = Array.prototype.slice.call(rich.children);
  const isRule = (t) => /^בימים שאין אומרים תחנון לא יאמר/.test(t);
  // קטע שכולו באותיות קטנות בסידור (מזמור כ' / "עד אנה") — כשאומרים אותו הוא מוצג בגודל רגיל
  const unsmall = (el) => {
    if (!el) return;
    const kids = Array.prototype.filter.call(el.childNodes, (n) => n.nodeType === 1 || strip(n.textContent));
    if (kids.length === 1 && kids[0].tagName === "SMALL") {
      const sm = kids[0];
      while (sm.firstChild) el.insertBefore(sm.firstChild, sm);
      sm.remove();
    }
  };
  let section = "pre"; // pre → viduy → rachel → leah
  ps.forEach((p, i) => {
    const t = strip(p.textContent);
    if (t === "תיקון רחל") section = "rachel";
    else if (t === "תיקון לאה") section = "leah";
    else if (section === "pre" && /^אנא יהוה אלהינו/.test(t)) section = "viduy";
    p.setAttribute("data-tc", section);
    // ── לשם יחוד: הוראת הסידור הארוכה מוחלפת בכרטיס הלילה; הנוסח מותאם למה שאומרים ──
    if (section === "pre" && t.indexOf("אין אומרים תיקון חצות") >= 0 && !p.__tcDone) {
      p.__tcDone = true;
      const inner = p.querySelector("small > small");
      if (inner) {
        let n = inner.nextSibling;
        inner.remove();
        for (let k = 0; k < 2 && n; k++) { const nx = n.nextSibling; if (n.nodeName === "BR") n.remove(); n = nx; }
      }
      unsmall(p);
      let h = p.innerHTML;
      h = h.replace(/\s*<small>\(בימים מיוחדים[\s\S]*?<\/small>/, "");
      const both = "תִיקוּן רָחֵל וְתִיקוּן לֵאָה";
      // "(שָׁרְשׁוֹ)" החלופי מוסר; כשאומרים תיקון אחד בלבד — "שָׁרְשָׁם" הופך ל"שָׁרְשׁוֹ"
      // (סדר סימני הניקוד בטקסט של ספריא משתנה — התאמה לפי האותיות בלבד)
      const NQ = "[\\u0591-\\u05C7]*";
      h = h.replace(new RegExp("\\s*<small>\\(ש" + NQ + "ר" + NQ + "ש" + NQ + "ו" + NQ + "\\)</small>"), "");
      const shorsham = new RegExp("ש" + NQ + "ר" + NQ + "ש" + NQ + "ם");
      if (!st.rachel && st.leah) h = h.replace(both, "תִיקוּן לֵאָה").replace(shorsham, "שָׁרְשׁוֹ");
      else if (st.rachel && !st.leah) h = h.replace(both, "תִיקוּן רָחֵל").replace(shorsham, "שָׁרְשׁוֹ");
      p.innerHTML = h;
    }
    // ── תיקון לאה: הוראות "בימים שאין אומרים תחנון" — מוחלות לפי הלילה ──
    if (section === "leah" && isRule(t)) {
      p.setAttribute("data-tc-rule", "1");
      const next = ps[i + 1];
      if (next) {
        if (st.noTachanun) next.setAttribute("data-tc-skip", "1");
        else unsmall(next);
      }
    }
  });
  const show = (sec, on) => rich.querySelectorAll('[data-tc="' + sec + '"]').forEach((el) => {
    const off = !on || el.hasAttribute("data-tc-rule") || el.hasAttribute("data-tc-skip");
    el.style.display = off ? "none" : "";
  });
  const none = !st.rachel && !st.leah;
  show("pre", true);
  show("viduy", st.rachel); // הוידוי שייך לתיקון רחל — בתיקון לאה בלבד אין אומרים וידוי
  show("rachel", st.rachel);
  show("leah", st.leah);
  // ── כרטיס הלילה ──
  let chz = "";
  try {
    const z = window._lastZData;
    const c = z && z.times && z.times.chatzotNight ? new Date(z.times.chatzotNight) : null;
    if (c && !isNaN(c)) chz = c.toLocaleTimeString("he-IL", { hour: "2-digit", minute: "2-digit", hour12: false });
  } catch (e) {}
  let what;
  if (none) what = "הלילה אין אומרים תיקון חצות (" + escapeHtml(st.reason) + ").";
  else if (st.rachel && st.leah) what = "אומרים <b>תיקון רחל ותיקון לאה</b> — ולפני תיקון רחל את הוידוי.";
  else if (st.leah) what = "אומרים <b>תיקון לאה בלבד</b> (" + escapeHtml(st.reason) + ") — בלי וידוי ובלי תיקון רחל." +
    (st.noTachanun ? " ביום שאין אומרים בו תחנון מדלגים בתיקון לאה על \"למנצח... יענך\" ועל \"עד אנה בכיה בציון\" — והם אינם מוצגים." : "");
  else what = "אומרים <b>תיקון רחל בלבד</b> (" + escapeHtml(st.reason) + ").";
  const card = document.createElement("div");
  card.className = "tc-status-card";
  card.innerHTML =
    '<div class="tc-status-title">🌙 ' + escapeHtml(st.nightLabel) + "</div>" +
    '<div class="tc-status-what">' + what + "</div>" +
    '<div class="tc-status-time">זמן האמירה: מחצות הלילה' + (chz ? " (" + chz + ")" : "") + " ועד עלות השחר.</div>" +
    st.notes.map((n) => '<div class="tc-status-note">' + escapeHtml(n) + "</div>").join("") +
    '<div class="tc-status-note">אבל, חתן, ואבי הבן ביום הברית — אומרים תיקון לאה בלבד.</div>' +
    (none ? '<button type="button" class="tc-show-full">הצג את הנוסח לימות החול</button>' : "");
  const old = root.querySelector(".tc-status-card");
  if (old) old.remove();
  root.insertBefore(card, root.firstChild);
  rich.style.display = none ? "none" : "";
  if (none) {
    const btn = card.querySelector(".tc-show-full");
    if (btn) btn.onclick = function () {
      rich.style.display = "";
      show("viduy", true); show("rachel", true); show("leah", true);
      btn.remove();
    };
  }
}

// ── כפתור הנעה לפעולה בסוף תפילה: מעבר ישיר לתפילה הבאה בסדר ──
// ברכות השחר (הכפתור העצמאי, לא בתוך שחרית) → קריאת שמע (הכפתור העצמאי "שמע ישראל")
const PRAYER_NEXT_CTA = {
  "birchot-hashachar": { key: "shema", he: "שמע ישראל", en: "Shema", label: "המשך לקריאת שמע ישראל" },
};
function _prayerNextCtaHtml(key) {
  const n = PRAYER_NEXT_CTA[key];
  if (!n) return "";
  return `<div class="prayer-next-cta-wrap"><button type="button" class="prayer-next-cta" onclick="window._prayerSwapTo('${n.key}','${n.he}','${n.en}')"><span class="prayer-next-cta-ico" aria-hidden="true">📜</span><span>${n.label}</span><span class="prayer-next-cta-arrow" aria-hidden="true">←</span></button></div>`;
}
window._prayerSwapTo = function (key, he, en) {
  window.__prayerSwapInPlace = true;
  openPrayer(key, he, en);
};

function toHebrewPsalmNumber(num) {
  // Traditional Hebrew/Jewish numbering used in Tanach, Mishna, halacha:
  //   15 → "טו" (9+6) — NOT "יה" (which spells part of the Divine Name)
  //   16 → "טז" (9+7) — NOT "יו" (same reason)
  // The 17/18/19 explicit entries are required because the greedy algorithm
  // would otherwise pick 16 first and produce "טזא"/"טזב"/"טזג" — which is wrong.
  const numerals = [
    [400, "ת"],
    [300, "ש"],
    [200, "ר"],
    [100, "ק"],
    [90, "צ"],
    [80, "פ"],
    [70, "ע"],
    [60, "ס"],
    [50, "נ"],
    [40, "מ"],
    [30, "ל"],
    [20, "כ"],
    [19, "יט"],
    [18, "יח"],
    [17, "יז"],
    [16, "טז"],
    [15, "טו"],
    [10, "י"],
    [9, "ט"],
    [8, "ח"],
    [7, "ז"],
    [6, "ו"],
    [5, "ה"],
    [4, "ד"],
    [3, "ג"],
    [2, "ב"],
    [1, "א"],
  ];
  let n = num;
  let out = "";
  numerals.forEach(([value, letter]) => {
    while (n >= value) {
      out += letter;
      n -= value;
    }
  });
  return out || String(num);
}

openTehillimPage = function () {
  const dayPlans = [
    {
      day: "ראשון",
      chapters: Array.from({ length: 29 }, (_, index) => index + 1),
    },
    {
      day: "שני",
      chapters: Array.from({ length: 21 }, (_, index) => index + 30),
    },
    {
      day: "שלישי",
      chapters: Array.from({ length: 22 }, (_, index) => index + 51),
    },
    {
      day: "רביעי",
      chapters: Array.from({ length: 17 }, (_, index) => index + 73),
    },
    {
      day: "חמישי",
      chapters: Array.from({ length: 17 }, (_, index) => index + 90),
    },
    {
      day: "שישי",
      chapters: Array.from({ length: 13 }, (_, index) => index + 107),
    },
    {
      day: "שבת",
      chapters: Array.from({ length: 31 }, (_, index) => index + 120),
    },
  ];
  const todayIndex = new Date().getDay();
  let activeIndex = todayIndex;
  let existing = document.getElementById("tehillim-modal");
  if (existing) {
    // פתיחה-כפולה: ניקוי הישן חייב לשחרר את הנעילה ואת רשומת המחסנית שלו —
    // אחרת נשארת נעילה תקועה והדף קופא לצמיתות אחרי הסגירה
    existing.remove();
    unlockBodyScroll();
    if (_activeModals[_activeModals.length - 1] === "tehillim-modal")
      _activeModals.pop();
  }

  const modal = document.createElement("div");
  modal.id = "tehillim-modal";
  modal.style.cssText =
    "position:fixed;inset:0;z-index:200;background:#faf9f6;display:flex;flex-direction:column;overflow:hidden;";

  const renderDay = (index) => {
    activeIndex = index;
    const plan = dayPlans[index];
    const rangeLabel = `${toHebrewPsalmNumber(plan.chapters[0])}-${toHebrewPsalmNumber(plan.chapters[plan.chapters.length - 1])}`;
    modal.innerHTML = `
            <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem 0.75rem;border-bottom:1px solid rgba(0,0,0,0.08);flex-shrink:0;background:#faf9f6;gap:0.5rem;">
              <div style="display:flex;align-items:center;gap:0.5rem;flex-shrink:0;">
                <button onclick="window._thToggleBMPanel()" id="th-bm-toggle-btn" style="background:rgba(0,0,0,0.06);border:none;color:#64748b;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:1rem;flex-shrink:0;" title="סמניות">📌</button>
              </div>
              <div style="text-align:center;min-width:0;">
                <h2 style="color:#000000;font-size:1.3rem;font-weight:900;margin:0;">ספר תהילים</h2>
                <p style="color:#1d4ed8;font-size:0.82rem;font-weight:700;margin:0.15rem 0 0;">יום ${plan.day} · פרקים ${rangeLabel}</p>
              </div>
              <button onclick="closeTehillimModal()" style="background:rgba(0,0,0,0.06);border:none;color:#64748b;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:1.1rem;flex-shrink:0;">✕</button>
            </div>
            <div id="th-bm-panel" style="display:none;position:absolute;top:84px;right:12px;left:12px;z-index:50;background:linear-gradient(168deg,#131f45 0%,#0a1330 100%);border:1px solid rgba(232,193,90,0.4);border-radius:1rem;padding:0.8rem 0.9rem;max-height:60vh;overflow-y:auto;direction:rtl;box-shadow:0 18px 48px rgba(0,0,0,0.55);max-width:440px;margin:0 auto;"></div>
            <div style="display:flex;gap:0.4rem;padding:0.75rem 1.25rem;overflow-x:auto;flex-shrink:0;background:#faf9f6;">
              ${dayPlans
                .map((item, itemIndex) => {
                  const itemRange = `${toHebrewPsalmNumber(item.chapters[0])}-${toHebrewPsalmNumber(item.chapters[item.chapters.length - 1])}`;
                  return `<button onclick="window._tehillimSwitchDay(${itemIndex})" style="padding:0.38rem 0.72rem;border-radius:999px;font-size:0.75rem;font-weight:700;border:1px solid ${itemIndex === index ? "#2563eb" : "rgba(0,0,0,0.12)"};background:${itemIndex === index ? "#2563eb" : "transparent"};color:${itemIndex === index ? "#fff" : "#64748b"};cursor:pointer;white-space:nowrap;">${item.day} · ${itemRange}</button>`;
                })
                .join("")}
            </div>
            <div style="padding:0 1.25rem 1.25rem;overflow-y:auto;flex:1;background:#faf9f6;">
              <p style="color:#64748b;font-size:0.76rem;margin:0 0 0.9rem;">לחיצה על פרק תפתח את הטקסט המלא של אותו פרק.</p>
              <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(92px,1fr));gap:0.55rem;">
                ${plan.chapters.map((chapter) => `<button onclick="window._tehillimOpenPsalm(${chapter})" style="background:rgba(0,0,0,0.03);border:1px solid rgba(0,0,0,0.1);border-radius:0.9rem;padding:0.7rem 0.6rem;font-size:0.82rem;font-weight:800;color:#000000;cursor:pointer;">פרק ${toHebrewPsalmNumber(chapter)}</button>`).join("")}
              </div>
              <div style="margin-top:1.5rem;padding-top:0.85rem;border-top:1px solid rgba(0,0,0,0.08);color:#94a3b8;font-size:0.74rem;line-height:1.6;text-align:center;">מקור הטקסט: <strong style="color:#1e40af;">Sefaria.org</strong> · ספר תהילים</div>
            </div>
            <div id="psalm-content-pane" style="display:none;position:absolute;inset:0;background:#faf9f6;z-index:10;flex-direction:column;overflow:hidden;">
              <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid rgba(0,0,0,0.08);background:#faf9f6;gap:0.5rem;">
                <div style="display:flex;align-items:center;gap:0.4rem;flex-shrink:0;">
                  <button class="toc-nav-btn" onclick="window._tehillimGoToChapters()" style="background:rgba(0,0,0,0.06);border:none;color:#64748b;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:1.15rem;display:flex;align-items:center;justify-content:center;flex-shrink:0;" title="תוכן העניינים — כל הפרקים" aria-label="תוכן העניינים">☰</button>
                  <button onclick="window._thTogglePsalmBMPanel()" id="th-psalm-bm-toggle-btn" style="background:rgba(0,0,0,0.06);border:none;color:#64748b;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:1rem;" title="סמניות">📌</button>
                </div>
                <h3 id="psalm-title" style="color:#000000;font-size:1rem;font-weight:900;margin:0;flex:1;text-align:center;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">תהילים</h3>
                <button onclick="window._tehillimClosePsalm()" style="background:rgba(0,0,0,0.06);border:none;color:#64748b;padding:0.4rem 0.8rem;border-radius:999px;cursor:pointer;font-size:0.8rem;font-weight:700;flex-shrink:0;">← חזרה</button>
              </div>
              <div id="th-psalm-bm-panel" style="display:none;position:absolute;top:72px;right:12px;left:12px;z-index:50;background:linear-gradient(168deg,#131f45 0%,#0a1330 100%);border:1px solid rgba(232,193,90,0.4);border-radius:1rem;padding:0.8rem 0.9rem;max-height:60vh;overflow-y:auto;direction:rtl;box-shadow:0 18px 48px rgba(0,0,0,0.55);max-width:440px;margin:0 auto;"></div>
              <div id="psalm-text-area" class="holy-text-style" style="padding:1.25rem;overflow-y:auto;flex:1;text-align:center;direction:rtl;"></div>
              <div id="tehillim-font-bar" class="flex items-center justify-center gap-3 py-2 px-4 flex-shrink-0" style="background:rgba(250,249,246,0.95);border-top:1px solid rgba(0,0,0,0.08);">
                <span class="font-btn-group" style="display:inline-flex;align-items:center;gap:0.75rem;flex-wrap:nowrap;flex-shrink:0;"><button onclick="changePrayerFontSize(-10, '#psalm-text-area')" style="width:38px;height:38px;border-radius:50%;border:1.5px solid rgba(99,102,241,0.3);background:linear-gradient(135deg,#eef2ff 0%,#e0e7ff 100%);color:#4338ca;font-size:1.25rem;font-weight:900;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(99,102,241,0.15);transition:transform 0.15s ease,box-shadow 0.15s ease;" onmouseover="this.style.transform='scale(1.08)';this.style.boxShadow='0 4px 10px rgba(99,102,241,0.25)';" onmouseout="this.style.transform='';this.style.boxShadow='0 2px 6px rgba(99,102,241,0.15)';" aria-label="הקטן כתב">−</button><button onclick="changePrayerFontSize(10, '#psalm-text-area')" style="width:38px;height:38px;border-radius:50%;border:1.5px solid rgba(99,102,241,0.3);background:linear-gradient(135deg,#eef2ff 0%,#e0e7ff 100%);color:#4338ca;font-size:1.25rem;font-weight:900;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(99,102,241,0.15);transition:transform 0.15s ease,box-shadow 0.15s ease;" onmouseover="this.style.transform='scale(1.08)';this.style.boxShadow='0 4px 10px rgba(99,102,241,0.25)';" onmouseout="this.style.transform='';this.style.boxShadow='0 2px 6px rgba(99,102,241,0.15)';" aria-label="הגדל כתב">+</button></span>
                <button type="button" class="rf-btn" onclick="window._openReaderFontPopup()" aria-label="בחירת פונט קריאה" title="בחירת פונט">א</button>
                <button onclick="window._toggleAutoScroll('#psalm-text-area', this)" style="width:38px;height:38px;border-radius:50%;border:1.5px solid rgba(16,185,129,0.35);background:linear-gradient(135deg,#ecfdf5 0%,#d1fae5 100%);color:#047857;font-size:0.95rem;font-weight:900;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 6px rgba(16,185,129,0.18);transition:transform 0.15s ease;" onmouseover="this.style.transform='scale(1.08)'" onmouseout="this.style.transform=''" aria-label="התחל גלילה אוטומטית">▶</button>
                <button class="auto-scroll-speed-btn" onclick="window._cycleAutoScrollSpeed(this)" style="font-size:0.78rem;font-weight:800;color:#047857;min-width:2.4rem;text-align:center;background:rgba(209,250,229,0.85);padding:5px 10px;border-radius:999px;border:1px solid rgba(16,185,129,0.3);cursor:pointer;" aria-label="מהירות גלילה">1x</button>
              </div>
            </div>
          `;
  };

  window._tehillimSwitchDay = (index) => { renderDay(index); window._thBuildBMPanel(); };

  // ── ניווט פרקים בתוך תהילים — פופ-אפ עם כל ק"נ פרקים ──
  window._tehillimGoToChapters = function() {
    var items = [];
    for (var n = 1; n <= 150; n++) {
      (function(num) {
        items.push({
          label: "פרק " + toHebrewPsalmNumber(num),
          isActive: (window._tehillimCurrentChapter === num),
          onClick: function() { window._tehillimOpenPsalm(num); }
        });
      })(n);
    }
    window._openChapterNavPopup({
      title: "מעבר לפרק תהילים",
      subtitle: "150 פרקים",
      color: "#1d4ed8",
      items: items
    });
  };
  window._tehillimLoadedChapters = new Set();
  window._tehillimCurrentChapter = 1;

  // Bookmarks
  const TH_BM_KEY = "tehillim_bookmarks_v1";
  const TH_LP_KEY = "tehillim_lastpos_v1";  // last position (separate from bookmarks)
  function thLoadBMs() { try { return JSON.parse(localStorage.getItem(TH_BM_KEY)||"[]"); } catch(e) { return []; } }
  function thSaveBMs(b) { try { localStorage.setItem(TH_BM_KEY, JSON.stringify(b)); } catch(e) {} }
  function thAddBM(ch) { const b=thLoadBMs(); if(!b.includes(ch)){b.push(ch);thSaveBMs(b);} }
  function thRemoveBM(ch) { thSaveBMs(thLoadBMs().filter(x=>x!==ch)); }
  function thIsBM(ch) { return thLoadBMs().includes(ch); }
  // Last position (separate from regular bookmarks)
  function thLoadLP() { try { return JSON.parse(localStorage.getItem(TH_LP_KEY)||"null"); } catch(e) { return null; } }
  function thSaveLP(ch, v) { try { localStorage.setItem(TH_LP_KEY, JSON.stringify({ ch: ch, v: v || null, ts: Date.now() })); } catch(e) {} }
  function thClearLP() { try { localStorage.removeItem(TH_LP_KEY); } catch(e) {} }
  // Find the verse currently at the top of the psalm-text-area viewport
  function thCurrentVisibleVerse(ch) {
    var area = document.getElementById("psalm-text-area");
    if (!area) return null;
    var verses = area.querySelectorAll('[id^="psalm-' + ch + '-v"]');
    if (!verses.length) return null;
    var rect = area.getBoundingClientRect();
    var bestV = null, bestDist = Infinity;
    for (var i = 0; i < verses.length; i++) {
      var r = verses[i].getBoundingClientRect();
      var dist = Math.abs(r.top - rect.top - 40);
      if (r.bottom < rect.top) continue;
      if (dist < bestDist) { bestDist = dist; bestV = parseInt(verses[i].getAttribute("data-verse")); }
    }
    return bestV;
  }
  window._thSaveLastPosition = function() {
    var ch = window._tehillimCurrentChapter;
    if (!ch) return false;
    var v = thCurrentVisibleVerse(ch);
    // טוגל: אם כבר שמור מיקום אחרון באותו פרק ופסוק — הלחיצה מסירה אותו
    var lp = thLoadLP();
    if (lp && lp.ch === ch && (lp.v || null) === (v || null)) {
      thClearLP();
      if (typeof window._thBuildBMPanel === "function") window._thBuildBMPanel();
      if (typeof window._thBuildPsalmBMPanel === "function") window._thBuildPsalmBMPanel();
      return "removed";
    }
    thSaveLP(ch, v);
    if (typeof window._thBuildBMPanel === "function") window._thBuildBMPanel();
    if (typeof window._thBuildPsalmBMPanel === "function") window._thBuildPsalmBMPanel();
    return true;
  };
  window._thRemoveLastPosition = function() { thClearLP(); if (typeof window._thBuildBMPanel === "function") window._thBuildBMPanel(); if (typeof window._thBuildPsalmBMPanel === "function") window._thBuildPsalmBMPanel(); };
  window._thGoLastPosition = function() {
    var lp = thLoadLP();
    if (!lp || !lp.ch || typeof window._tehillimOpenPsalm !== "function") return;
    window._tehillimOpenPsalm(lp.ch);
    if (lp.v) {
      setTimeout(function() {
        var el = document.getElementById("psalm-" + lp.ch + "-v" + lp.v);
        if (el) el.scrollIntoView({ behavior: "auto", block: "start" });
      }, 600);
    }
  };
  window._thToggleBM = (ch) => {
    const wasAdded = !thIsBM(ch);
    if (thIsBM(ch)) { thRemoveBM(ch); } else { thAddBM(ch); }
    const btn = document.getElementById("th-bm-btn-"+ch);
    if (btn) {
      const active = thIsBM(ch);
      const _dk = document.documentElement.classList.contains("dark");
      btn.textContent = active ? "🔖 מסומן" : "🔖 סמן";
      btn.style.border = active ? "1.5px solid " + (_dk ? "#b45309" : "#f59e0b") : "1.5px solid " + (_dk ? "#475569" : "#d1d5db");
      btn.style.color = active ? (_dk ? "#fbbf24" : "#92400e") : (_dk ? "#94a3b8" : "#64748b");
      btn.style.background = active ? (_dk ? "rgba(245,158,11,0.18)" : "#fffbeb") : "transparent";
    }
    window._thBuildBMPanel();
    if (window._thBuildPsalmBMPanel) window._thBuildPsalmBMPanel();
    if (typeof window.showToast === "function") {
      wasAdded ? window.showToast("🔖 הסימנייה נשמרה", "success", 2200) : showBookmarkRemovedToast();
    }
  };

  // שורות אחידות לשני פאנלי תהילים — עיצוב snbm הכלל-אתרי (09/2026)
  const _thBMRowsHtml = (fromPsalm) => {
    const bms = thLoadBMs().slice().sort((a,b)=>a-b);
    const lp = thLoadLP();
    const fr = fromPsalm ? 1 : 0;
    let html = "";
    let count = bms.length + (lp && lp.ch ? 1 : 0);
    if (lp && lp.ch) {
      html += window._bmRowHtml(
        { label: "מיקום אחרון — פרק " + toHebrewPsalmNumber(lp.ch) + (lp.v ? " פסוק " + toHebrewPsalmNumber(lp.v) : ""), isLastPos: true, ts: lp.ts },
        "window._thBMPanelGoLP(" + fr + ")",
        "window._thRemoveLastPosition()",
        ""
      );
    }
    html += bms.map(ch => window._bmRowHtml(
      { label: "פרק " + toHebrewPsalmNumber(ch) },
      "window._thBMPanelGo(" + ch + "," + fr + ")",
      "window._thToggleBM(" + ch + ")",
      ""
    )).join("");
    return { count: count, html: html };
  };
  // ניווט משורת פאנל: סוגרים את הפאנל (סינכרונית) ואז פותחים את הפרק/המיקום
  const _thBMPanelDismiss = (fromPsalm) => {
    const pid = fromPsalm ? "th-psalm-bm-panel" : "th-bm-panel";
    window._popupSyncDismiss(pid);
    const hider = window._popupHideHandlers[pid];
    if (hider) { try { hider(); } catch (e) {} }
    else { const el = document.getElementById(pid); if (el) el.style.display = "none"; }
  };
  window._thBMPanelGo = (ch, fromPsalm) => { _thBMPanelDismiss(fromPsalm); window._tehillimOpenPsalm(ch); };
  window._thBMPanelGoLP = (fromPsalm) => { _thBMPanelDismiss(fromPsalm); window._thGoLastPosition(); };
  window._thBuildBMPanel = () => {
    const panel = document.getElementById("th-bm-panel");
    if (!panel) return;
    const rows = _thBMRowsHtml(0);
    panel.innerHTML =
      window._bmHeadHtml("🔖 סימניות <small>תהילים</small>", rows.count, "window._thToggleBMPanel();") +
      (rows.count ? rows.html
        : window._bmEmptyHtml("אין סימניות שמורות עדיין",
            "לחצו על 🔖 שבראש הפרק כדי לסמן,<br>או על 📌 הצף כדי לשמור את המיקום האחרון"));
  };

  window._thToggleBMPanel = () => {
    window._bmStripToggle("th-bm-panel", window._thBuildBMPanel, '[onclick*="_thToggleBMPanel"]');
  };

  window._thBuildPsalmBMPanel = () => {
    const panel = document.getElementById("th-psalm-bm-panel");
    if (!panel) return;
    const rows = _thBMRowsHtml(1);
    panel.innerHTML =
      window._bmHeadHtml("🔖 סימניות <small>תהילים</small>", rows.count, "window._thTogglePsalmBMPanel();") +
      (rows.count ? rows.html
        : window._bmEmptyHtml("אין סימניות שמורות עדיין",
            "לחצו על 🔖 שבראש הפרק כדי לסמן,<br>או על 📌 הצף כדי לשמור את המיקום האחרון"));
  };

  window._thTogglePsalmBMPanel = () => {
    window._bmStripToggle("th-psalm-bm-panel", window._thBuildPsalmBMPanel, '[onclick*="_thTogglePsalmBMPanel"]');
  };

  // Psalm reading pane back-navigation
  window._tehillimOnPsalmClose = () => {
    const pane = document.getElementById("psalm-content-pane");
    if (pane) pane.style.display = "none";
  };

  window._tehillimClosePsalm = () => {
    if (_activeModals[_activeModals.length - 1] === "tehillim-psalm-pane") {
      history.back(); // popstate will call _tehillimOnPsalmClose
    } else {
      window._tehillimOnPsalmClose && window._tehillimOnPsalmClose();
    }
  };

  // פרק שנבנה מחוץ למסך נכנס מעל התוכן הקיים בלי להזיז את מה שעל המסך (פיצוי גלילה באותה משימה)
  function _thPrependKeep(area, div) {
    const anchor = area.firstElementChild;
    const t0 = anchor ? anchor.getBoundingClientRect().top : 0;
    area.insertBefore(div, area.firstChild);
    if (anchor) {
      const d = anchor.getBoundingClientRect().top - t0;
      if (d) area.scrollTop += d;
    }
  }
  // deferPrepend: הפרק הקודם בפתיחת פרק — נבנה מחוץ למסך ונכנס מעל רק כשהוא מוכן
  async function loadPsalmChapter(chapter, area, prepend, deferPrepend) {
    if (
      chapter < 1 ||
      chapter > 150 ||
      window._tehillimLoadedChapters.has(chapter)
    )
      return;
    window._tehillimLoadedChapters.add(chapter);
    const chapterDiv = document.createElement("div");
    chapterDiv.id = `psalm-chapter-${chapter}`;
    chapterDiv.style.cssText =
      "margin-bottom:2rem;padding-bottom:1.5rem;border-bottom:1px solid rgba(0,0,0,0.08);";
    // "טוען..." רק אם הטעינה באמת נמשכת (.ux-ph), והטקסט שמגיע נכנס ברכות (_uxSoftIn) — עד
    // 09/2026 ההודעה הבהבה לרגע והפסוקים "קפצו" פנימה
    chapterDiv.innerHTML = `<h4 style="color:#1e40af;font-size:1.1rem;font-weight:900;margin-bottom:0.75rem;text-align:center;">תהילים פרק ${toHebrewPsalmNumber(chapter)}</h4><p class="ux-ph" style="color:#94a3b8;text-align:center;">טוען...</p>`;
    const _thPh = _uxPhMark();
    const _thTok = window._tehillimLoadedChapters;
    if (!deferPrepend) {
      if (prepend && area.firstChild) {
        area.insertBefore(chapterDiv, area.firstChild);
      } else {
        area.appendChild(chapterDiv);
      }
    }
    try {
      const data = await _sefariaJson(
        `https://www.sefaria.org/api/texts/Psalms.${chapter}?lang=he&context=0`,
      );
      const verses = (data.he || [])
        .map(
          (verse, index) =>
            `<p id="psalm-${chapter}-v${index + 1}" data-verse="${index + 1}" style="margin:0.3rem 0;color:#000000;"><strong style="color:#1d4ed8;font-size:0.75rem;">(${toHebrewPsalmNumber(index + 1)})</strong> ${verse}</p>`,
        )
        .join("");
      const bmActive = thIsBM(chapter);
      const bmBtn = `<div style="text-align:center;margin-bottom:0.75rem;"><button id="th-bm-btn-${chapter}" onclick="window._thToggleBM(${chapter})" style="font-size:0.78rem;font-weight:700;padding:0.3rem 0.85rem;border-radius:999px;cursor:pointer;border:${bmActive?"1.5px solid #f59e0b":"1.5px solid #d1d5db"};color:${bmActive?"#92400e":"#64748b"};background:${bmActive?"#fffbeb":"transparent"};">${bmActive?"🔖 מסומן":"🔖 סמן"}</button></div>`;
      chapterDiv.innerHTML = `<h4 style="color:#1e40af;font-size:1.1rem;font-weight:900;margin-bottom:0.5rem;text-align:center;">תהילים פרק ${toHebrewPsalmNumber(chapter)}</h4>${bmBtn}${verses || "<p>לא נמצא טקסט.</p>"}`;
    } catch (error) {
      chapterDiv.innerHTML = `<h4 style="color:#1e40af;font-size:1.1rem;font-weight:900;margin-bottom:0.75rem;text-align:center;">תהילים פרק ${toHebrewPsalmNumber(chapter)}</h4><p style="color:#ef4444;">לא הצלחתי לטעון פרק זה.</p>`;
    }
    if (deferPrepend) {
      // נפתח בינתיים פרק אחר (סט חדש) או שהקורא נסגר — לא מכניסים לקורא של מישהו אחר
      if (area.isConnected && window._tehillimLoadedChapters === _thTok) _thPrependKeep(area, chapterDiv);
    } else if (chapterDiv.isConnected) {
      _uxSoftIn(Array.prototype.slice.call(chapterDiv.children, 1), _thPh);
    }
  }

  window._tehillimOpenPsalm = async (chapter) => {
    const pane = document.getElementById("psalm-content-pane");
    const title = document.getElementById("psalm-title");
    const area = document.getElementById("psalm-text-area");
    if (!pane || !title || !area) return;
    if (_activeModals[_activeModals.length - 1] !== "tehillim-psalm-pane") {
      pushModalState("tehillim-psalm-pane");
    }
    if (pane.style.display !== "flex" && typeof window._uxEnterView === "function") window._uxEnterView(pane);
    pane.style.display = "flex";
    window._tehillimLoadedChapters = new Set();
    window._tehillimCurrentChapter = chapter;
    const _thOpenT = Date.now();
    title.textContent = `תהילים פרק ${toHebrewPsalmNumber(chapter)}`;
    area.innerHTML = "";
    area.style.cssText =
      "padding:1.25rem;overflow-y:auto;flex:1;font-family:'Frank Ruhl Libre','David Libre',serif;font-size:25px;font-weight:700;line-height:1.7;color:#000000;text-align:center;direction:rtl;";
    applyPrayerFontSize("#psalm-text-area");
    // הפרק המבוקש נטען ומוצג ראשון; הקודם נבנה מחוץ למסך ונכנס מעליו רק כשהוא מוכן — בלי להזיז
    // את מה שעל המסך; הבא נוסף מתחת. עד 09/2026 הקודם נטען ראשון: בכניסה לפרק נראה קודם הטקסט
    // של הפרק הקודם, ואחרי שהכול נטען הקורא "קפץ" לפרק המבוקש
    await loadPsalmChapter(chapter, area, false);
    // Scroll to current chapter — לא אם כבר שינו גודל כתב בזמן הטעינה (השורה שנקראת נשמרה)
    const currentEl = document.getElementById(`psalm-chapter-${chapter}`);
    if (currentEl && !_fontScrollAnchorSince(area, _thOpenT)) currentEl.scrollIntoView({ block: "start" });
    if (chapter > 1) await loadPsalmChapter(chapter - 1, area, true, true);
    if (chapter < 150) await loadPsalmChapter(chapter + 1, area, false);
    // Infinite scroll: load more chapters on scroll
    // שמירת state ל-throttle ו-guard (מניעת race conditions בגלילה מהירה/אוטומטית)
    let _thScrollBusy = false;
    let _thScrollLastT = 0;
    area.onscroll = async function () {
      // Throttle: מתחסם את ה handler ל-50ms כדי לא להצימף את ה-CPU בגלילה בפיקסלים
      const _now = performance.now();
      if (_now - _thScrollLastT < 50) return;
      _thScrollLastT = _now;
      // Re-entry guard: אם עוד באמצע fetch/טעינה - לא להתחיל חדש
      if (_thScrollBusy) return;
      _thScrollBusy = true;
      try {
      const scrollTop = area.scrollTop;
      const scrollHeight = area.scrollHeight;
      const clientHeight = area.clientHeight;
      // Near bottom: load next chapter
      if (scrollHeight - scrollTop - clientHeight < 200) {
        const maxLoaded = Math.max(...window._tehillimLoadedChapters);
        if (maxLoaded < 150) await loadPsalmChapter(maxLoaded + 1, area, false);
      }
      // Near top: load previous chapter
      if (scrollTop < 200) {
        const minLoaded = Math.min(...window._tehillimLoadedChapters);
        if (minLoaded > 1) {
          // Anchor-based: שומרים את הפרק העליון הנוכחי כאנכור ומתקנים לפי ההזזה בפעל
          const _thAnchor = area.querySelector('[id^="psalm-chapter-"]');
          const _thAnchorTopBefore = _thAnchor ? _thAnchor.getBoundingClientRect().top : 0;
          await loadPsalmChapter(minLoaded - 1, area, true);
          if (_thAnchor) {
            const _thAnchorTopAfter = _thAnchor.getBoundingClientRect().top;
            area.scrollTop += (_thAnchorTopAfter - _thAnchorTopBefore);
          }
        }
      }
      // Update title based on visible chapter
      const chapters = area.querySelectorAll("[id^='psalm-chapter-']");
      for (const ch of chapters) {
        const rect = ch.getBoundingClientRect();
        const areaRect = area.getBoundingClientRect();
        if (rect.top >= areaRect.top - 50 && rect.top < areaRect.top + 150) {
          const num = parseInt(ch.id.replace("psalm-chapter-", ""));
          if (num && title) {
            const _thTitleTxt = `תהילים פרק ${toHebrewPsalmNumber(num)}`;
            // כתיבה רק בשינוי — כתיבת טקסט זהה בכל אירוע גלילה מייצרת ריצוד
            if (title.textContent !== _thTitleTxt) title.textContent = _thTitleTxt;
          }
          break;
        }
      }
      } finally {
        _thScrollBusy = false;
      }
    };
  };

  renderDay(activeIndex);
  document.body.appendChild(modal);
  lockBodyScroll();
  pushModalState("tehillim-modal");
};

