  function yerHalSecs(en, perChapter) {
    var arr = [], empty = YER_EMPTY_HALAKHOT[en] || {};
    for (var c = 1; c <= perChapter.length; c++) {
      for (var h = 1; h <= perChapter[c - 1]; h++) {
        if (empty[c] && empty[c].indexOf(h) >= 0) continue;
        arr.push({ he: "פרק " + toHN(c) + " · הלכה " + toHN(h), ref: "Jerusalem_Talmud_" + en + "." + c + "." + h });
      }
    }
    return arr;
  }
