    var key = (_sbk ? _sbk.id : "") + "|" + secIdx + (paraIdx !== null ? "|" + paraIdx : "") + "|__LP__";
    var sections = _sbk ? _sbk.sections : (_bk.sections||[]);
    var s = _bk.type === "hardcoded" ? {he:_bk.he} : (sections[secIdx]||{he:""});
    var paraLabel = paraIdx !== null ? " — " + toHN(paraIdx + 1) : "";
